item.content:encoded:
/* Halaman detail artikel */
.single-post .entry-title,
.single-post .page-title{
  font-size:clamp(30px,5vw,48px);
  line-height:1.15;
  font-weight:800;
  color:#1A1A2E;
}
.single-post .entry-meta{color:#8B1034;font-weight:600;font-size:14px}
.single-post .wp-post-image,
.single-post .ct-media-container,
.single-post .ct-featured-image{border-radius:24px;overflow:hidden}
.single-post .entry-content{font-size:18px;line-height:1.85;color:#333}
.single-post .entry-content > *{max-width:720px;margin-left:auto;margin-right:auto}
.single-post .entry-content h2{font-size:28px;color:#1A1A2E;margin-top:2em}
.single-post .entry-content a{color:#8B1034}
.single-post .post-tags a,
.single-post .entry-tags a{
  background:#FBF4F4;color:#8B1034;border-radius:999px;
  padding:6px 14px;font-size:13px;text-decoration:none;
}
